INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Shirt of a Happy Man', 'Long ago, there lived a king who had everything. He had power, wealth, and a grand palace. But the king was not happy. Day after day, he felt grey and sad. He called in many doctors, but none of them could help. One day, a wise doctor said, "To make the king happy, find the shirt of a truly happy man. The king must wear it." So the king''s men looked everywhere. At last, they found a happy man. He was singing in a field. "Are you really happy?" they asked. "Yes, I am the happiest man alive," he said. But when they asked for his shirt, they were surprised. The happy man had no shirt at all!', '记叙文', 118, '[{"q": "What did the king have?", "answer": "D", "options": ["Many friends.", "No money.", "A small house.", "Power, wealth, and a palace."], "explanation": "原文:power, wealth, and a grand palace"}, {"q": "Was the king happy?", "answer": "B", "options": ["Yes.", "No.", "Always.", "Sometimes."], "explanation": "原文:the king was not happy"}, {"q": "What did the wise doctor say would help?", "answer": "C", "options": ["A new palace.", "More money.", "The shirt of a truly happy man.", "More power."], "explanation": "原文:find the shirt of a truly happy man"}, {"q": "Where did they find the happy man?", "answer": "B", "options": ["In a palace.", "Singing in a field.", "In a city.", "In a shop."], "explanation": "原文:singing in a field"}, {"q": "What surprised the king''s men?", "answer": "C", "options": ["He was rich.", "He was sad.", "The happy man had no shirt.", "He was a king."], "explanation": "原文:had no shirt at all"}]'::jsonb, '[{"word": "king", "cn": "国王"}, {"word": "power", "cn": "权力;力量"}, {"word": "wealth", "cn": "财富"}]'::jsonb, 3, '9', 'U11');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Winning Team', 'Peter was new on the soccer team. He felt like there was a heavy weight on his shoulders because he had let his team down. In the last game, he had missed an important goal, and his team had lost. He was afraid the coach would kick him off the team. After the game, the coach called Peter in. "It''s not your fault," the coach said. "We win and lose as a team." His teammates nodded in agreement. "You have the courage to keep trying," said his friend. "That''s what makes you a good player." Peter felt a great sense of relief. He realized that real friends pull together. They do not let each other down.', '记叙文', 116, '[{"q": "Why did Peter feel a heavy weight?", "answer": "C", "options": ["He was new.", "He was tired.", "He had let his team down.", "He was sick."], "explanation": "原文:he had let his team down"}, {"q": "What did Peter do in the last game?", "answer": "B", "options": ["He scored a goal.", "He missed an important goal.", "He was late.", "He got hurt."], "explanation": "原文:missed an important goal"}, {"q": "What was Peter afraid of?", "answer": "C", "options": ["Losing money.", "Moving away.", "Being kicked off the team.", "Getting hurt."], "explanation": "原文:coach would kick him off the team"}, {"q": "What did the coach say?", "answer": "A", "options": ["It''s not your fault.", "You are late.", "You are out.", "You are slow."], "explanation": "原文:It''s not your fault"}, {"q": "What did Peter realize?", "answer": "B", "options": ["Soccer is hard.", "Real friends pull together.", "He is the best.", "He should quit."], "explanation": "原文:real friends pull together"}]'::jsonb, '[{"word": "weight", "cn": "重量;分量"}, {"word": "coach", "cn": "教练"}, {"word": "relief", "cn": "轻松;解脱"}]'::jsonb, 3, '9', 'U11');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'What Makes Us Happy?', 'What makes people happy? Many people think that money and fame make us happy. But this is not always true. A rich banker may have wealth, but he can still feel sad and lonely. Studies show that good friendships make us happier than money. When we are with friends, we feel relaxed and warm. Helping others also makes us happy. The more we give, the more joy we feel. Doing things we love, like music or sports, makes us feel alive. So happiness does not come from things we own. It comes from the people we love and the things we enjoy. True happiness is found in the heart, not in the wallet.', '议论文', 113, '[{"q": "What do many people think makes us happy?", "answer": "C", "options": ["Friends only.", "Sports only.", "Money and fame.", "Music only."], "explanation": "原文:money and fame make us happy"}, {"q": "Is this always true?", "answer": "A", "options": ["No.", "Yes.", "Often.", "Sometimes."], "explanation": "原文:this is not always true"}, {"q": "What makes us happier than money?", "answer": "A", "options": ["Good friendships.", "More wealth.", "More work.", "More fame."], "explanation": "原文:good friendships make us happier"}, {"q": "What happens the more we give?", "answer": "D", "options": ["The poorer we are.", "The sadder we feel.", "The less we have.", "The more joy we feel."], "explanation": "原文:The more we give, the more joy we feel"}, {"q": "Where is true happiness found?", "answer": "C", "options": ["In the wallet.", "In money.", "In the heart.", "In fame."], "explanation": "原文:in the heart, not in the wallet"}]'::jsonb, '[{"word": "fame", "cn": "名声;声誉"}, {"word": "banker", "cn": "银行家"}, {"word": "friendship", "cn": "友谊"}]'::jsonb, 3, '9', 'U11');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'How Music Affects Us', 'Music has a strong effect on our feelings. Different kinds of music make us feel different things. Soft, quiet music can make us feel calm and relaxed. It can help us sleep or study better. Fast, loud music can make us feel excited and full of energy. It is great for sports or parties. Sad music can even make some people cry, but it can also help them feel better afterwards. Happy songs make us want to dance and smile. Music can also bring back memories. A song from our childhood can make us think of the past. This is why music is such an important part of our lives.', '说明文', 110, '[{"q": "What does music have a strong effect on?", "answer": "D", "options": ["Our age.", "Our height.", "Our money.", "Our feelings."], "explanation": "原文:strong effect on our feelings"}, {"q": "What can soft, quiet music make us feel?", "answer": "D", "options": ["Excited.", "Tired.", "Angry.", "Calm and relaxed."], "explanation": "原文:make us feel calm and relaxed"}, {"q": "What is fast, loud music great for?", "answer": "A", "options": ["Sports or parties.", "Sleeping.", "Resting.", "Studying."], "explanation": "原文:great for sports or parties"}, {"q": "What can sad music help people do afterwards?", "answer": "D", "options": ["Forget music.", "Stop crying never.", "Feel worse.", "Feel better."], "explanation": "原文:help them feel better afterwards"}, {"q": "What can a childhood song make us think of?", "answer": "A", "options": ["The past.", "Food.", "The future.", "Money."], "explanation": "原文:make us think of the past"}]'::jsonb, '[{"word": "effect", "cn": "影响;效果"}, {"word": "calm", "cn": "平静的"}, {"word": "energy", "cn": "精力;能量"}]'::jsonb, 3, '9', 'U11');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'A True Friend', 'Holly and Amy had been friends for years. But lately, they had not been getting along. Amy felt that Holly was leaving her out. Holly always spent time with her new friends. One day, Amy decided to talk to Holly rather than stay angry. "I feel hurt when you leave me out," Amy said. Holly was surprised. "I''m sorry," she said. "I didn''t mean to make you feel that way. You are still my best friend." The two girls talked for a long time. In the end, their friendship was stronger than before. Amy learned that a true friend will talk about problems, not run away from them.', '记叙文', 108, '[{"q": "How long had Holly and Amy been friends?", "answer": "B", "options": ["For days.", "For years.", "For a month.", "For a week."], "explanation": "原文:friends for years"}, {"q": "What did Amy feel Holly was doing?", "answer": "A", "options": ["Leaving her out.", "Calling her.", "Visiting her.", "Helping her."], "explanation": "原文:Holly was leaving her out"}, {"q": "What did Amy decide to do?", "answer": "B", "options": ["Stay angry.", "Talk to Holly.", "Run away.", "Find new friends."], "explanation": "原文:talk to Holly rather than stay angry"}, {"q": "How did Holly feel when Amy told her?", "answer": "A", "options": ["Surprised.", "Angry.", "Happy.", "Bored."], "explanation": "原文:Holly was surprised"}, {"q": "What did Amy learn?", "answer": "D", "options": ["Friends are hard.", "Run away.", "Stay angry.", "A true friend talks about problems."], "explanation": "原文:talk about problems, not run away"}]'::jsonb, '[{"word": "lately", "cn": "最近"}, {"word": "friendship", "cn": "友谊"}, {"word": "leave", "cn": "离开;留下"}]'::jsonb, 3, '9', 'U11');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Friendship Week Notice', 'FRIENDSHIP WEEK IS COMING! Friends make our lives better. This week, let''s celebrate our friendships! MONDAY: Write a thank-you card to a friend. Tell them what makes them special. TUESDAY: Have lunch with someone new. It is a good way to make new friends. WEDNESDAY: Help a classmate with their work. Helping others makes us both happy. THURSDAY: Share a happy memory with a friend. Good memories pull us together. FRIDAY: Play a team game. Remember, we win and lose as a team. Let''s make this a week full of kindness. After all, a life with good friends is a happy life!', '应用文', 102, '[{"q": "What does the notice celebrate?", "answer": "A", "options": ["Friendships.", "Music.", "Food.", "Sports."], "explanation": "原文:celebrate our friendships"}, {"q": "What should you do on Monday?", "answer": "B", "options": ["Play a game.", "Write a thank-you card to a friend.", "Have lunch.", "Help a classmate."], "explanation": "原文:Monday: Write a thank-you card"}, {"q": "What is a good way to make new friends?", "answer": "D", "options": ["Play games.", "Write cards.", "Stay alone.", "Have lunch with someone new."], "explanation": "原文:have lunch with someone new"}, {"q": "What makes us both happy on Wednesday?", "answer": "C", "options": ["Playing games.", "Writing cards.", "Helping others.", "Eating lunch."], "explanation": "原文:Helping others makes us both happy"}, {"q": "What do we do on Friday?", "answer": "C", "options": ["Have lunch.", "Write a card.", "Play a team game.", "Share a memory."], "explanation": "原文:Friday: Play a team game"}]'::jsonb, '[{"word": "friendship", "cn": "友谊"}, {"word": "memory", "cn": "记忆;回忆"}, {"word": "kindness", "cn": "善良;友好"}]'::jsonb, 3, '9', 'U11');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U11', 'The Unhappy King', 'Long ago, there lived a (1)____ who had everything. He had power, wealth, and a grand (2)____. But he was not (3)____. Day after day, he felt grey and (4)____. He called (5)____ many doctors, but none could help. One wise doctor said, "To make the king (6)____, find the shirt of a truly happy man." So the king''s men (7)____ everywhere. At last, they found a happy man singing in a (8)____. But when they asked for his shirt, they were (9)____. The happy man had no shirt at all! This story shows that wealth does not always (10)____ people happy.', 102, 3, '[{"q": "1", "answer": "C", "options": ["price", "game", "king", "color"], "explanation": "国王 king"}, {"q": "2", "answer": "A", "options": ["palace", "price", "color", "game"], "explanation": "宫殿 palace"}, {"q": "3", "answer": "B", "options": ["busy", "happy", "sad", "tired"], "explanation": "快乐 happy"}, {"q": "4", "answer": "D", "options": ["proud", "happy", "glad", "sad"], "explanation": "悲伤 sad"}, {"q": "5", "answer": "C", "options": ["up", "out", "in", "off"], "explanation": "call in 召来"}, {"q": "6", "answer": "B", "options": ["tired", "happy", "sad", "busy"], "explanation": "快乐 happy"}, {"q": "7", "answer": "A", "options": ["looked", "broke", "threw", "lost"], "explanation": "寻找 looked"}, {"q": "8", "answer": "B", "options": ["game", "field", "price", "color"], "explanation": "田野 field"}, {"q": "9", "answer": "D", "options": ["tired", "calm", "happy", "surprised"], "explanation": "惊讶 surprised"}, {"q": "10", "answer": "A", "options": ["make", "lose", "throw", "break"], "explanation": "使…快乐 make happy"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U11', 'Peter and the Team', 'Peter was new on the soccer (1)____. He felt a heavy weight on his (2)____ because he had let his team (3)____. In the last game, he missed an important (4)____, and the team lost. He was afraid the coach would (5)____ him off the team. After the game, the coach called him (6)____. "It''s not your (7)____," the coach said. "We win and lose as a (8)____." His teammates nodded in (9)____. Peter felt a great sense of (10)____. He learned that real friends pull together.', 87, 3, '[{"q": "1", "answer": "B", "options": ["color", "team", "game", "price"], "explanation": "球队 team"}, {"q": "2", "answer": "D", "options": ["games", "colors", "prices", "shoulders"], "explanation": "肩膀 shoulders"}, {"q": "3", "answer": "B", "options": ["off", "down", "up", "in"], "explanation": "let down 使失望"}, {"q": "4", "answer": "A", "options": ["goal", "color", "price", "game"], "explanation": "进球 goal"}, {"q": "5", "answer": "A", "options": ["kick", "break", "throw", "lose"], "explanation": "kick off 开除"}, {"q": "6", "answer": "C", "options": ["out", "up", "in", "off"], "explanation": "call in 叫来"}, {"q": "7", "answer": "C", "options": ["color", "price", "fault", "game"], "explanation": "过错 fault"}, {"q": "8", "answer": "B", "options": ["price", "team", "game", "color"], "explanation": "团队 team"}, {"q": "9", "answer": "A", "options": ["agreement", "game", "price", "color"], "explanation": "同意 agreement"}, {"q": "10", "answer": "D", "options": ["color", "game", "price", "relief"], "explanation": "轻松 relief"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U11', 'What Makes Us Happy', 'Many people think that money and (1)____ make us happy. But this is not always (2)____. A rich banker may have great (3)____, but he can still feel (4)____ and lonely. Studies show that good (5)____ make us happier than money. When we are with friends, we feel (6)____ and warm. Helping others also makes us (7)____. The more we (8)____, the more joy we feel. So happiness does not come from the things we (9)____. It comes from the people we love. True happiness is found in the (10)____, not in the wallet.', 94, 3, '[{"q": "1", "answer": "B", "options": ["price", "fame", "color", "game"], "explanation": "名声 fame"}, {"q": "2", "answer": "D", "options": ["bad", "wrong", "false", "true"], "explanation": "真实 true"}, {"q": "3", "answer": "A", "options": ["wealth", "game", "price", "color"], "explanation": "财富 wealth"}, {"q": "4", "answer": "A", "options": ["sad", "glad", "happy", "proud"], "explanation": "悲伤 sad"}, {"q": "5", "answer": "B", "options": ["colors", "friendships", "games", "prices"], "explanation": "友谊 friendships"}, {"q": "6", "answer": "A", "options": ["relaxed", "angry", "tired", "busy"], "explanation": "放松 relaxed"}, {"q": "7", "answer": "C", "options": ["busy", "tired", "happy", "sad"], "explanation": "快乐 happy"}, {"q": "8", "answer": "B", "options": ["throw", "give", "lose", "break"], "explanation": "给予 give"}, {"q": "9", "answer": "D", "options": ["break", "lose", "throw", "own"], "explanation": "拥有 own"}, {"q": "10", "answer": "C", "options": ["game", "color", "heart", "price"], "explanation": "内心 heart"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U11', 'Music and Feelings', 'Music has a strong (1)____ on our feelings. Soft, quiet music can make us feel (2)____ and relaxed. It can help us (3)____ better. Fast, loud music can make us feel (4)____ and full of energy. It is great for (5)____ or parties. Sad music can even make some people (6)____, but it can also help them feel (7)____ afterwards. Happy songs make us want to (8)____ and smile. Music can also bring back (9)____. A song from our childhood can make us think of the (10)____. This is why music is so important in our lives.', 97, 3, '[{"q": "1", "answer": "A", "options": ["effect", "price", "color", "game"], "explanation": "影响 effect"}, {"q": "2", "answer": "A", "options": ["calm", "loud", "fast", "angry"], "explanation": "平静 calm"}, {"q": "3", "answer": "C", "options": ["lose", "throw", "sleep", "break"], "explanation": "睡 sleep"}, {"q": "4", "answer": "B", "options": ["tired", "excited", "bored", "calm"], "explanation": "兴奋 excited"}, {"q": "5", "answer": "D", "options": ["prices", "games", "colors", "sports"], "explanation": "运动 sports"}, {"q": "6", "answer": "C", "options": ["break", "throw", "cry", "lose"], "explanation": "哭 cry"}, {"q": "7", "answer": "B", "options": ["colder", "better", "worse", "smaller"], "explanation": "更好 better"}, {"q": "8", "answer": "A", "options": ["dance", "throw", "lose", "break"], "explanation": "跳舞 dance"}, {"q": "9", "answer": "D", "options": ["colors", "games", "prices", "memories"], "explanation": "回忆 memories"}, {"q": "10", "answer": "B", "options": ["game", "past", "price", "color"], "explanation": "过去 past"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U11', 'A True Friend', 'Holly and Amy had been friends for (1)____. But lately, they had not been getting (2)____. Amy felt that Holly was leaving her (3)____. One day, Amy decided to (4)____ to Holly rather than stay angry. "I feel (5)____ when you leave me out," Amy said. Holly was (6)____. "I''m sorry," she said. "I didn''t mean to make you feel that (7)____." The two girls talked for a long (8)____. In the end, their friendship was (9)____ than before. Amy learned that a true friend will talk about problems, not (10)____ away from them.', 94, 3, '[{"q": "1", "answer": "B", "options": ["games", "years", "prices", "colors"], "explanation": "多年 years"}, {"q": "2", "answer": "B", "options": ["color", "along", "game", "price"], "explanation": "get along 相处"}, {"q": "3", "answer": "D", "options": ["up", "in", "off", "out"], "explanation": "leave out 忽略"}, {"q": "4", "answer": "C", "options": ["throw", "lose", "talk", "break"], "explanation": "谈 talk"}, {"q": "5", "answer": "A", "options": ["hurt", "glad", "happy", "proud"], "explanation": "受伤 hurt"}, {"q": "6", "answer": "C", "options": ["calm", "tired", "surprised", "happy"], "explanation": "惊讶 surprised"}, {"q": "7", "answer": "A", "options": ["way", "price", "game", "color"], "explanation": "方式 that way"}, {"q": "8", "answer": "D", "options": ["game", "color", "price", "time"], "explanation": "时间 a long time"}, {"q": "9", "answer": "A", "options": ["stronger", "weaker", "smaller", "colder"], "explanation": "更强 stronger"}, {"q": "10", "answer": "B", "options": ["lose", "run", "throw", "break"], "explanation": "逃避 run away"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U11', 'Friendship Week', 'Friendship Week is coming! Friends make our lives (1)____. On Monday, write a thank-you (2)____ to a friend. Tell them what makes them (3)____. On Tuesday, have lunch with someone (4)____. It is a good way to make new (5)____. On Wednesday, (6)____ a classmate with their work. Helping others makes us both (7)____. On Thursday, share a happy (8)____ with a friend. Good memories pull us (9)____. On Friday, play a team game. Let''s make this a week full of (10)____. After all, a life with good friends is a happy life!', 93, 3, '[{"q": "1", "answer": "A", "options": ["better", "colder", "worse", "smaller"], "explanation": "更好 better"}, {"q": "2", "answer": "C", "options": ["color", "game", "card", "price"], "explanation": "卡片 card"}, {"q": "3", "answer": "B", "options": ["wrong", "special", "sad", "bad"], "explanation": "特别 special"}, {"q": "4", "answer": "B", "options": ["cold", "new", "old", "sad"], "explanation": "新 new"}, {"q": "5", "answer": "A", "options": ["friends", "prices", "colors", "games"], "explanation": "朋友 friends"}, {"q": "6", "answer": "A", "options": ["help", "throw", "break", "lose"], "explanation": "帮助 help"}, {"q": "7", "answer": "B", "options": ["sad", "happy", "tired", "busy"], "explanation": "快乐 happy"}, {"q": "8", "answer": "C", "options": ["price", "color", "memory", "game"], "explanation": "回忆 memory"}, {"q": "9", "answer": "D", "options": ["apart", "away", "alone", "together"], "explanation": "一起 together"}, {"q": "10", "answer": "D", "options": ["price", "color", "game", "kindness"], "explanation": "善良 kindness"}]'::jsonb, 6);
