INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U11 听力·对话 The Soccer Team', '九年级 Unit11 听力·情绪与友谊/使役动词make', 2, 'W: You look sad. What''s wrong?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U11 听力·短文 How Music Affects Us', '九年级 Unit11 听力·情绪与友谊/使役动词make', 2, 'Music has a strong effect on our feelings.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U11 听力·对话 Two Friends', '九年级 Unit11 听力·情绪与友谊/使役动词make', 2, 'W: You seem upset. Is everything OK with Holly?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U11 听力·短文 Friendship Week', '九年级 Unit11 听力·情绪与友谊/使役动词make', 2, 'Friendship Week is coming, and friends make our lives better.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'What Makes Me Happy', '用使役动词make(make me + 动词原形/形容词)写一篇短文,介绍什么让你快乐、什么让你难过,以及朋友或音乐如何影响你的情绪。60词左右。', 'Write a short passage on the topic: "What Makes Me Happy".', '["什么让你快乐(makes me happy / makes me smile)", "什么让你难过或紧张(makes me sad/nervous)", "朋友或音乐如何影响你(makes me feel...)", "你从中明白了什么"]'::jsonb, 70, 100, 'Many things in my life affect how I feel. Good music makes me feel relaxed and calm. When I am tired, a happy song makes me want to dance. Sad movies make me cry, but they also make me think. My friends make my life better. When I am down, they make me smile again. The more time I spend with them, the happier I feel. I have learned that happiness comes from the people and things we love.', 'content:含快乐/难过的事/朋友或音乐的影响/感悟(4分)；language:正确使用make sb. do/make sb.+形容词(3分)；structure:语句通顺、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'What Makes Me Happy', '["... makes me happy/sad", "... makes me feel ...", "... makes me cry/laugh", "Music makes me ...", "Friends make my life better", "The more ... the more ..."]'::jsonb, '[]'::jsonb, '要点:什么让你快乐(makes me happy / makes me smile)；什么让你难过或紧张(makes me sad/nervous)；朋友或音乐如何影响你(makes me feel...)；你从中明白了什么', '9', 'U11' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U11' AND topic='What Makes Me Happy');
